###############################################################
## Find continuous position blocks
###############################################################

find_blocks <- function(pos)
{

    blocks <- list()

    start <- pos[1]

    previous <- pos[1]


    counter <- 1


    if(length(pos) == 1)
    {
        blocks[[1]] <- c(
            start,
            previous
        )

        return(blocks)
    }


    for(i in 2:length(pos))
    {

        if(pos[i] == previous + 1)
        {

            previous <- pos[i]

        }
        else
        {

            blocks[[counter]] <- c(
                start,
                previous
            )

            counter <- counter + 1

            start <- pos[i]

            previous <- pos[i]

        }

    }


    blocks[[counter]] <- c(
        start,
        previous
    )


    return(blocks)

}


blocks <- find_blocks(
    positions
)



